create table if not exists public.music(id text primary key, book text, lg text, ed text, ch text, su text, page_from int, page_to int, feeling text[], txt_id text, sort numeric, updated_at timestamptz default now());
create or replace view public.music_vw as select r.id, r.desc as song, btrim(split_part(r.desc,';',1)) as title, btrim(split_part(r.desc,';',2)) as artist, r.url as spotify, r.qr, t.txt, m.book, m.lg, m.ed, m.ch, m.su, m.page_from, m.page_to, m.feeling, m.sort, m.updated_at from public.redir r left join public.music m on m.id=r.id left join public.redir t on t.id=coalesce(m.txt_id,r.id) where r."group"='Music';
